&lt;div class=&quot;presentation navmenu&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les lignages de sanguin&lt;a class=&quot;headeranchor&quot; id=&quot;Les_lignages_de_sanguin_0&quot; href=&quot;#Les_lignages_de_sanguin_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td width=&quot;33%&quot;&gt;
  &lt;ul&gt;
    &lt;li&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Aberrant-(Sanguin).html&quot; title=&quot;Lignage Aberrant&quot;&gt;Aberrant&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Abyssal-(Sanguin).html&quot; title=&quot;Lignage Abyssal&quot;&gt;Abyssal&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-C&#233;leste-(Sanguin).html&quot; title=&quot;Lignage C&#233;leste&quot;&gt;C&#233;leste&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Draconique-(Sanguin).html&quot; title=&quot;Lignage Draconique&quot;&gt;Draconique&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-&#201;l&#233;mentaire-(Sanguin).html&quot; title=&quot;Lignage &#201;l&#233;mentaire&quot;&gt;&#201;l&#233;mentaire&lt;/a&gt;&lt;/li&gt;
  &lt;/ul&gt;
&lt;/td&gt;&lt;td width=&quot;33%&quot;&gt;
  &lt;ul&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lignage-F&#233;&#233;rique-(Sanguin).html&quot; title=&quot;Lignage F&#233;&#233;rique&quot;&gt;F&#233;&#233;rique&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Infernal-(Sanguin).html&quot; title=&quot;Lignage Infernal&quot;&gt;Infernal&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Kyton.html&quot; title=&quot;Lignage Kyton&quot;&gt;Kyton&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Mort-Vivant-(Sanguin).html&quot; title=&quot;Lignage Mort-vivant&quot;&gt;Mort-vivant&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Profane-(Sanguin).html&quot; title=&quot;Lignage Profane&quot;&gt;Profane&lt;/a&gt;&lt;/li&gt;
  &lt;/ul&gt;
&lt;/td&gt;
&lt;td width=&quot;33%&quot;&gt;
  &lt;ul&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Sang-Noir-(Sanguin).html&quot; title=&quot;Lignage Sang noir&quot;&gt;Sang noir&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Vou&#233;-&#192;-Un-Grand-Destin-(Sanguin).html&quot; title=&quot;Lignage Vou&#233; &#224; un grand destin&quot;&gt;Vou&#233; &#224; un grand destin&lt;/a&gt;&lt;/li&gt;
  &lt;/ul&gt;
  &lt;ul&gt;
    &lt;li&gt;La classe de &lt;a class=&quot;pagelink&quot; href=&quot;Sanguin.html&quot; title=&quot;Le sanguin&quot;&gt;Sanguin&lt;/a&gt;&lt;/li&gt;
  &lt;/ul&gt;
&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - Classes avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Class Guide/Manuel des joueurs - Classes avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMCA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Un dragon s’est m&#234;l&#233; &#224; la lign&#233;e du personnage, quelque part dans son histoire familiale. &#192; pr&#233;sent, les antiques pouvoirs de ce sublime monstre alimentent sa rage sanguine.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Dons suppl&#233;mentaires.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Puissance.html&quot; title=&quot;Attaque en puissance&quot;&gt;Attaque en puissance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Combat-En-Aveugle.html&quot; title=&quot;Combat en aveugle&quot;&gt;Combat en aveugle&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Encha&#238;nement.html&quot; title=&quot;Encha&#238;nement&quot;&gt;Encha&#238;nement&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Robustesse.html&quot; title=&quot;Robustesse&quot;&gt;Robustesse&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-Linitiative.html&quot; title=&quot;Science de l&amp;#39;initiative&quot;&gt;Science de l’initiative&lt;/a&gt;,
&lt;a class=&quot;pagelink&quot; href=&quot;Talent.html&quot; title=&quot;Talent&quot;&gt;Talent&lt;/a&gt; (Vol), &lt;a class=&quot;pagelink&quot; href=&quot;Vigueur-Surhumaine.html&quot; title=&quot;Vigueur surhumaine&quot;&gt;Vigueur surhumaine&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;
&lt;b&gt;Sorts suppl&#233;mentaires.&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier.html&quot; title=&quot;Bouclier&quot;&gt;Bouclier&lt;/a&gt;&lt;/i&gt; (7), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-Aux-&#201;nergies-Destructives.html&quot; title=&quot;R&#233;sistance aux &#233;nergies destructives&quot;&gt;r&#233;sistance aux &#233;nergies destructives&lt;/a&gt;&lt;/i&gt; (10), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-Vol.html&quot; title=&quot;Vol&quot;&gt;vol&lt;/a&gt;&lt;/i&gt; (13), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Terreur.html&quot; title=&quot;Terreur&quot;&gt;terreur&lt;/a&gt;&lt;/i&gt; (16).&lt;br /&gt;&lt;br /&gt;
&lt;h2 class=&quot;separator&quot;&gt;Pouvoirs de lignage&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoirs_de_lignage_0&quot; href=&quot;#Pouvoirs_de_lignage_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Le pouvoir des dragons impr&#232;gne le personnage et se manifeste de diverses mani&#232;res. &lt;br /&gt;&lt;br /&gt;&lt;div style=&quot;float:right; background-color: #fff; padding: 0 0 8px 10px&quot;&gt;
&lt;div style=&quot;border: 1px solid #4b3124; padding: 4px; max-width: 260px;&quot;&gt;
&lt;table CLASS=&quot;tablo centre toutgauche autoalt&quot; ID=&quot;tabdragon&quot;&gt;&lt;caption&gt;lignage draconique&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Type de Dragon&lt;/td&gt;&lt;td&gt;Type d&#39;&#233;nergie&lt;/td&gt;&lt;td&gt;Forme du souffle&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;Blanc&lt;/td&gt;&lt;td&gt;Froid&lt;/td&gt;&lt;td&gt;C&#244;ne de 9m&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Bleu&lt;/td&gt;&lt;td&gt;&#201;lectricit&#233;&lt;/td&gt;&lt;td&gt;Ligne de 18m&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Noir&lt;/td&gt;&lt;td&gt;Acide&lt;/td&gt;&lt;td&gt;Ligne de 18m&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Rouge&lt;/td&gt;&lt;td&gt;Feu&lt;/td&gt;&lt;td&gt;C&#244;ne de 9m&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Vert&lt;/td&gt;&lt;td&gt;Acide&lt;/td&gt;&lt;td&gt;C&#244;ne de 9m&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Airain&lt;/td&gt;&lt;td&gt;Feu&lt;/td&gt;&lt;td&gt;Ligne de 18m&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Argent&lt;/td&gt;&lt;td&gt;Froid&lt;/td&gt;&lt;td&gt;C&#244;ne de 9m&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Bronze&lt;/td&gt;&lt;td&gt;&#201;lectricit&#233;&lt;/td&gt;&lt;td&gt;Ligne de 18m&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Cuivre&lt;/td&gt;&lt;td&gt;Acide&lt;/td&gt;&lt;td&gt;Ligne de 18m&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Or&lt;/td&gt;&lt;td&gt;Feu&lt;/td&gt;&lt;td&gt;C&#244;ne de 9m &lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;/div&gt;Au niveau 1, il doit choisir un type de dragon m&#233;tallique ou chromatique. Il ne peut pas en changer par la suite. Une partie de ses pouvoirs de lignage infligent des d&#233;g&#226;ts et offrent des r&#233;sistances bas&#233;s sur le type de dragon, comme indiqu&#233; plus loin.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;GRIFFES&quot; href=&quot;#GRIFFES&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Griffes (Sur).&lt;/b&gt; &#192; partir du niveau 1, le personnage a des griffes qui poussent. Elles fonctionnent comme des &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples#Attaquenaturelle.html&quot; title=&quot;armes naturelles&quot;&gt;armes naturelles&lt;/a&gt; qui lui permettent d’effectuer deux attaques de griffe lors d’une &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Complexes#Attaqueaoutrance.html&quot; title=&quot;attaque &#224; outrance&quot;&gt;attaque &#224; outrance&lt;/a&gt;, en appliquant son &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;bonus de base &#224; l’attaque&lt;/a&gt; maximal. Ces attaques infligent 1d6 points de d&#233;g&#226;ts (1d4 si le personnage est de taille P) plus le modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; du personnage. D&#232;s le niveau 4, ces griffes sont consid&#233;r&#233;es comme des armes magiques vis-&#224;-vis de la &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;r&#233;duction aux d&#233;g&#226;ts&lt;/a&gt;. &#192; partir du niveau 8, les d&#233;g&#226;ts passent &#224; 1d8 (1d6 pour un personnage de taille P). Au niveau 12, les griffes infligent 1d6 points de d&#233;g&#226;ts du type d’&#233;nergie destructive associ&#233; au personnage en plus &#224; chaque fois qu’elles touchent.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;RESISTANCESDRACONIQUES&quot; href=&quot;#RESISTANCESDRACONIQUES&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;R&#233;sistances draconiques (Ext).&lt;/b&gt; Au niveau 4, le personnage gagne une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-(Capacit&#233;).html&quot; title=&quot;R&#233;sistance (aux &#233;nergies destructrices) (Ext)&quot;&gt;r&#233;sistance&lt;/a&gt; de 5 contre son type d’&#233;nergie destructive et un bonus d’armure naturelle de +1 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;. Au niveau 8, la r&#233;sistance passe &#224; 10 et le bonus d’armure naturelle &#224; +2. Au niveau 16, le bonus d’armure naturelle passe &#224; +4.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;SOUFFLE&quot; href=&quot;#SOUFFLE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Souffle Sur).&lt;/b&gt; Au niveau 8, le personnage gagne une attaque de souffle utilisable une fois par jour. Elle inflige 1d6 points de d&#233;g&#226;ts d’&#233;nergie du m&#234;me type que le dragon du lignage du personnage par niveau de sanguin. Les cr&#233;atures qui se trouvent dans la zone d’effet ont droit &#224; un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;R&#233;flexes&quot;&gt;R&#233;flexes&lt;/a&gt; pour r&#233;duire les d&#233;g&#226;ts de moiti&#233;. Le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; de ce jet est de 10 +1/2 niveau de sanguin du personnage + son modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt;. La forme du souffle d&#233;pend du type de dragon du personnage (comme indiqu&#233; dans la table pr&#233;c&#233;dente). Au niveau 16, le personnage peut utiliser ce pouvoir deux fois par jour et au niveau 20 trois fois par jour.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;AILESDEDRAGON&quot; href=&quot;#AILESDEDRAGON&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Ailes de dragon(Sur).&lt;/b&gt; Au niveau 12, quand le personnage d&#233;cha&#238;ne sa rage sanguine, il peut d&#233;cider de se faire pousser des ailes de dragon dans le dos, ce qui lui conf&#232;re une vitesse de vol de 18 m&#232;tres et une manœuvrabilit&#233; moyenne. Au niveau 16, sa vitesse de vol passe &#224; 24 m&#232;tres avec une bonne manœuvrabilit&#233;.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;FORMEDRACONIQUE&quot; href=&quot;#FORMEDRACONIQUE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Forme draconique(Sur).&lt;/b&gt; Au niveau 16, quand le personnage entre en rage sanguine, il peut prendre la forme de son type de dragon (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-Draconique-Ii.html&quot; title=&quot;Forme draconique II&quot;&gt;forme draconique II&lt;/a&gt;&lt;/i&gt; mais avec une manœuvrabilit&#233; moyenne ou bonne, comme celle que lui donne le pouvoir de rage sanguine ailes de dragon).&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;POUVOIRDESDRACOSIRES&quot; href=&quot;#POUVOIRDESDRACOSIRES&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Pouvoir des dracosires(Sur).&lt;/b&gt; Au niveau 20, le personnage est &lt;a class=&quot;pagelink&quot; href=&quot;Immunit&#233;-(Capacit&#233;).html&quot; title=&quot;Immunit&#233; (Ext ou Sur)&quot;&gt;immunis&#233;&lt;/a&gt; contre la &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Paralys&#233;.html&quot; title=&quot;Paralys&#233;&quot;&gt;paralysie&lt;/a&gt;, le sommeil et les d&#233;g&#226;ts de son type d’&#233;nergie destructive. Il gagne aussi &lt;a class=&quot;pagelink&quot; href=&quot;Perception-Aveugle-(Capacit&#233;).html&quot; title=&quot;Perception aveugle (Ext)&quot;&gt;perception aveugle&lt;/a&gt; &#224; 18 m&#232;tres. Il b&#233;n&#233;ficie en permanence de ces avantages et pas seulement quand il est enrag&#233;.
